import * as THREE from 'three';
import type { ModelName } from '../asset-catalog';
import type { AssetLibrary } from '../assets';
import { CELL_U } from '../atlas';
import { bufferGeometryOf, triangleCount, type MeshData } from '../mesh-data';

const STRIDE = 9;

/** A model of the manifest, or a model generated by the code (flowers, mushrooms). */
export type GeneratedModel = `gen:${string}`;
export type InstanceModel = ModelName | GeneratedModel;

/**
 * Collects placements of repeated models, then builds one `InstancedMesh` per model
 * (one draw call each). Each instance can pick its atlas column for leaves and accents.
 */
export class InstanceBatch {
  private readonly items = new Map<InstanceModel, number[]>();
  private readonly custom = new Map<GeneratedModel, MeshData>();
  private readonly owned: THREE.BufferGeometry[] = [];

  constructor(private readonly assets: AssetLibrary) {}

  /** Triangles of all the placed instances (no GPU object needed). */
  countTriangles(): number {
    let total = 0;
    for (const [name, list] of this.items) {
      const data = this.custom.get(name as GeneratedModel) ?? this.assets.data(name as ModelName);
      total += triangleCount(data) * (list.length / STRIDE);
    }
    return total;
  }

  /** Register a generated model under a name. */
  register(name: GeneratedModel, data: MeshData): void {
    this.custom.set(name, data);
  }

  add(
    model: InstanceModel,
    x: number,
    y: number,
    z: number,
    yaw: number,
    scale: number,
    scaleY = scale,
    leafColumn = 0,
    accentColumn = 0,
  ): void {
    let list = this.items.get(model);
    if (!list) {
      list = [];
      this.items.set(model, list);
    }
    list.push(x, y, z, yaw, scale, scaleY, scale, leafColumn * CELL_U, accentColumn * CELL_U);
  }

  count(model: InstanceModel): number {
    return (this.items.get(model)?.length ?? 0) / STRIDE;
  }

  private source(name: InstanceModel): THREE.BufferGeometry {
    const custom = this.custom.get(name as GeneratedModel);
    if (custom) {
      const geometry = bufferGeometryOf(custom);
      this.owned.push(geometry);
      return geometry;
    }
    return this.assets.geometry(name as ModelName);
  }

  build(
    options: (model: InstanceModel) => {
      material: THREE.Material;
      depthMaterial?: THREE.Material;
      castShadow: boolean;
    },
  ): THREE.InstancedMesh[] {
    const meshes: THREE.InstancedMesh[] = [];
    const matrix = new THREE.Matrix4();
    const position = new THREE.Vector3();
    const quaternion = new THREE.Quaternion();
    const scale = new THREE.Vector3();
    for (const [name, list] of this.items) {
      const n = list.length / STRIDE;
      const source = this.source(name);
      // Own geometry object for the per-instance attribute; vertex buffers stay shared.
      const geometry = new THREE.BufferGeometry();
      for (const key of ['position', 'normal', 'uv']) {
        geometry.setAttribute(key, source.getAttribute(key));
      }
      geometry.setIndex(source.getIndex());
      const swatch = new Float32Array(n * 2);
      const { material, depthMaterial, castShadow } = options(name);
      const mesh = new THREE.InstancedMesh(geometry, material, n);
      for (let i = 0; i < n; i++) {
        const o = i * STRIDE;
        position.set(list[o], list[o + 1], list[o + 2]);
        quaternion.setFromAxisAngle(THREE.Object3D.DEFAULT_UP, list[o + 3]);
        scale.set(list[o + 4], list[o + 5], list[o + 6]);
        mesh.setMatrixAt(i, matrix.compose(position, quaternion, scale));
        swatch[i * 2] = list[o + 7];
        swatch[i * 2 + 1] = list[o + 8];
      }
      geometry.setAttribute('aSwatch', new THREE.InstancedBufferAttribute(swatch, 2));
      mesh.instanceMatrix.needsUpdate = true;
      mesh.castShadow = castShadow;
      mesh.receiveShadow = true;
      if (depthMaterial && castShadow) mesh.customDepthMaterial = depthMaterial;
      // The whole diorama is always in view.
      mesh.frustumCulled = false;
      mesh.name = name;
      this.owned.push(geometry);
      meshes.push(mesh);
    }
    return meshes;
  }

  dispose(): void {
    // Shared library buffers are released with the library; only wrappers are owned here.
    for (const geometry of this.owned) geometry.dispose();
    this.owned.length = 0;
  }
}
